FROM sys_module_item
WHERE id = #{id}
  AND module_name = #{moduleName}

SELECT id, module_name, name, code, status, description, create_time, update_time
FROM sys_module_item
WHERE module_name = #{moduleName}
ORDER BY id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(1)
FROM sys_module_item
WHERE module_name = #{moduleName}

